create or replace function public.amqm_admin_dashboard_snapshot() returns jsonb language plpgsql security definer set search_path=public as $$ declare tid uuid; begin if public.my_role() not in ('super_admin','admin','principal') then raise exception 'Administrator access required'; end if; select id into tid from public.terms where is_current=true order by starts_on desc limit 1; return jsonb_build_object('term_id',tid,'term',(select jsonb_build_object('id',t.id,'name',t.name,'term_number',t.term_number,'starts_on',t.starts_on,'ends_on',t.ends_on,'lifecycle_status',t.lifecycle_status) from public.terms t where t.id=tid),'students',(select count(*) from public.students s where s.status='active'),'day_students',(select count(*) from public.students s where s.status='active' and s.section::text='day'),'boarding_students',(select count(*) from public.students s where s.status='active' and s.section::text='boarding'),'active_staff',(select count(*) from public.profiles p where p.employment_status='active' and p.role<>'parent'),'teachers',(select count(*) from public.profiles p where p.employment_status='active' and p.role='teacher'),'evaluations_total',(select count(*) from public.evaluations e where e.term_id=tid),'evaluations_pending',(select count(*) from public.evaluations e where e.term_id=tid and e.status='pending_approval'),'evaluations_approved',(select count(*) from public.evaluations e where e.term_id=tid and e.status='approved'),'attendance_today',(select count(*) from public.attendance_records a where a.attendance_date=(now() at time zone 'Africa/Lagos')::date and a.person_type='student'),'attendance_present_today',(select count(*) from public.attendance_records a join public.attendance_statuses st on st.code=a.status_code where a.attendance_date=(now() at time zone 'Africa/Lagos')::date and a.person_type='student' and st.counts_as_present),'fees_due',(select coalesce(sum(sf.amount_due),0) from public.student_fees sf join public.fee_structures fs on fs.id=sf.fee_structure_id where fs.term_id=tid),'fees_paid',(select coalesce(sum(sf.amount_paid),0) from public.student_fees sf join public.fee_structures fs on fs.id=sf.fee_structure_id where fs.term_id=tid)); end $$; grant execute on function public.amqm_admin_dashboard_snapshot() to authenticated;
create or replace function public.amqm_teacher_operational_evaluations() returns setof public.evaluations language sql security definer set search_path=public as $$ select e.* from public.evaluations e join public.terms t on t.id=e.term_id where public.my_role()='teacher' and e.teacher_id=auth.uid() and t.is_current=true order by e.teacher_visible_at desc nulls last,e.submitted_at desc nulls last limit 1000; $$; grant execute on function public.amqm_teacher_operational_evaluations() to authenticated;
